272	export async function listNotifications(
273	  input: ListNotificationsInput,
274	): Promise<Page<Notification>> {
275	  const db = getDb();
276	  const sort = { sortColumn: notifications.createdAt, idColumn: notifications.id };
277	
278	  const filters = compact(
279	    orgPredicate(notifications.orgId, input.orgId),
280	    eq(notifications.recipientId, input.recipientId),
281	    input.unreadOnly ? isNull(notifications.readAt) : undefined,
282	    input.kind === undefined || input.kind.length === 0
283	      ? undefined
284	      : inArray(notifications.kind, [...input.kind]),
285	  );
286	
287	  const total = db
288	    .select({ value: count() })
289	    .from(notifications)
290	    .where(and(...filters))
291	    .get();
292	
293	  const rows = db
294	    .select()
295	    .from(notifications)
296	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
297	    .orderBy(desc(notifications.createdAt), desc(notifications.id))
298	    .limit(probeLimit(input.limit))
299	    .all();
300	
301	  return toPage(rows, input.limit, total?.value ?? 0, toNotification, (row) => ({
302	    id: row.id,
303	    sortValue: row.createdAt,
304	  }));
305	}
