534	/**
535	 * Builds the daily digest bundle per recipient from unread notifications inside the org's digest window.
536	 *
537	 * Must call (do not reimplement): isEnabled, renderEmail
538	 */
539	import { isEnabled } from "@/lib/feature-flags";
540	import { DIGEST_MAX_ENTRIES } from "@/config/constants";
541	import * as notificationRepo from "@/server/repositories/notification-repository";
542	import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
543	import * as orgRepo from "@/server/repositories/organization-repository";
544	import { renderEmail } from "./email-service";
545	import { buildFlagContext } from "./feature-flag-service";
546	import type { RenderedEmail } from "@/server/services/email-service";
547	import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
548	import type { User } from "@/types/member";
549	import type { DigestBundle, DigestEntry } from "@/types/notification";
550	
551	/** A digest with fewer entries than this is not worth an email. */
552	const MIN_ENTRIES = 1;
553	
554	/**
555	 * Collects one recipient's unread notifications inside the window. Returns
556	 * `null` — rather than an empty bundle — when the org's plan does not include
557	 * the digest, or when there is nothing to say: the caller treats `null` as
558	 * "send nothing", so a quiet day produces no mail at all.
559	 */
560	export async function buildDigest(
561	  orgId: OrgId,
562	  recipientId: UserId,
563	  windowStart: IsoTimestamp,
564	  windowEnd: IsoTimestamp,
565	): Promise<DigestBundle | null> {
566	  const org = await orgRepo.findOrgById(orgId);
567	  if (!org) return null;
568	
569	  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;
570	
571	  const unread = await notificationRepo.listUnreadSince(
572	    orgId,
573	    recipientId,
574	    windowStart,
575	  );
576	
577	  const entries: DigestEntry[] = unread
578	    .filter((notification) => notification.createdAt <= windowEnd)
579	    .map((notification) => ({
580	      notificationId: notification.id,
581	      kind: notification.kind,
582	      title: notification.title,
583	      href: notification.href,
584	      occurredAt: notification.createdAt,
585	    }))
586	    .slice(0, DIGEST_MAX_ENTRIES);
587	
588	  if (entries.length < MIN_ENTRIES) return null;
589	
590	  return { orgId, recipientId, entries, windowStart, windowEnd };
591	}
