618	/**
619	 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
620	 *
621	 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
622	 */
623	import { isEnabled } from "@/lib/feature-flags";
624	import { createLogger } from "@/lib/logger";
625	import * as notificationRepo from "@/server/repositories/notification-repository";
626	import * as orgRepo from "@/server/repositories/organization-repository";
627	import * as usageRepo from "@/server/repositories/usage-repository";
628	import * as userRepo from "@/server/repositories/user-repository";
629	import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
630	import { sendEmail } from "@/server/services/email-service";
631	import { buildFlagContext } from "@/server/services/feature-flag-service";
632	import { toIsoTimestamp } from "@/types/common";
633	import { runJob } from "./types";
634	import type { JobResult } from "@/server/jobs/types";
635	import type { Organization } from "@/types/organization";
636	
637	const ORG_BATCH = 50;
638	const MS_PER_DAY = 24 * 60 * 60 * 1000;
639	
640	const logger = createLogger("digest-email-job");
641	
642	/**
643	 * One pass per scheduler tick. Each org is only processed during the UTC hour
644	 * it configured, so a tick that runs every few minutes still sends exactly one
645	 * digest per day per recipient.
646	 */
647	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
648	  return runJob("digest-email", async (result) => {
649	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
650	
651	    for (const orgId of orgIds) {
652	      const org = await orgRepo.findOrgById(orgId);
653	      if (!org || !shouldRunForOrg(org, now)) continue;
654	
655	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
656	
657	      const windowEnd = toIsoTimestamp(now);
658	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
659	
660	      for (const recipientId of await listDigestRecipients(orgId)) {
661	        try {
662	          const bundle = await buildDigest(
663	            orgId,
664	            recipientId,
665	            windowStart,
666	            windowEnd,
667	          );
668	          if (!bundle) continue;
669	
670	          const recipient = await userRepo.findUserById(recipientId);
671	          if (!recipient) continue;
672	
673	          const rendered = await renderDigest(bundle, recipient);
674	          await sendEmail({ to: recipient.email, ...rendered });
675	
676	          // Once digested, these notifications are no longer "unread" — this
677	          // is what keeps a later run inside the same window from sending
678	          // the same digest twice.
679	          for (const entry of bundle.entries) {
680	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
681	          }
682	
683	          result.processed += 1;
684	        } catch (error) {
685	          result.failed += 1;
686	          logger.error("digest failed", {
687	            orgId,
688	            recipientId,
689	            reason: error instanceof Error ? error.message : String(error),
690	          });
691	        }
692	      }
693	    }
694	  });
695	}
