697	/**
698	 * True during the org's configured digest hour. Exported because the schedule
699	 * decision is worth testing on its own, without a database.
700	 */
701	export function shouldRunForOrg(org: Organization, now: Date): boolean {
702	  if (org.archivedAt !== null) return false;
703	  return now.getUTCHours() === org.settings.digestHourUtc;
704	}
705	/**
706	 * Global user rows. The only repository that is NOT tenant scoped — users exist across organizations.
