  const other = await createTenant("rejoin-other", "growth");
  const { token: token2 } = await sessionService.createSessionToken(t.userIds.viewer);
  await memberRepo.insertMember(other.org.id, t.userIds.viewer, "member", null);
  getDb().update(sessions).set({ activeOrgId: t.org.id }).where(eq(sessions.tokenHash, hashToken(token))).run();
  getDb().update(sessions).set({ activeOrgId: other.org.id }).where(eq(sessions.tokenHash, hashToken(token2))).run();
  await prefRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.viewer, kind: "comment_created", inApp: true, email: true, digestOnly: true });

  await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id });
  expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(3);
  expect((await memberRepo.listMembers({ orgId: t.org.id, limit: 50, cursor: null })).total).toBe(3);
  expect(getDb().select().from(sessions).where(eq(sessions.tokenHash, hashToken(token))).get()?.activeOrgId).toBeNull();
  expect((await sessionService.resolveSession(token2))?.activeOrgId).toBe(other.org.id);
  expect(await notify(t.org.id, "issue_assigned", [t.userIds.viewer], { title: "x", body: "x", href: "/", actorId: null })).toHaveLength(0);
  expect(await listDigestRecipients(t.org.id)).toEqual([]);
  await expect(memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: viewer.id })).rejects.toThrow();
  expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(3);

  const invitation = await inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "VIEWER@rejoin.test", role: "admin" });
  expect(invitation.role).toBe("admin");
  const raw = "r".repeat(32);
  getDb().run(`update invitations set token_hash = '${hashToken(raw)}' where id = '${invitation.id}'` as any);
  const back = await inv.acceptInvitation(t.userIds.viewer, { token: raw });
  expect(back.id).toBe(viewer.id);
  expect(back).toMatchObject({ role: "admin", status: "active", archivedAt: null, invitedBy: t.userIds.admin });
  const stored = await invitationRepo.findInvitationById(t.org.id, invitation.id);
  expect(back.joinedAt).toBe(stored?.acceptedAt);
  expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(4);
  expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
  expect(await memberService.resolveActor(t.userIds.viewer, t.org.id)).toMatchObject({ role: "admin" });
