it("new joiner is active, seats are pending-only, duplicates refused", async () => {
  const t = await createTenant("seats", "starter"); // 10 seats, 4 members
  const exp = await seedInvite(t.org.id, t.userIds.admin, "old@seats.test", "viewer", "e".repeat(32), -20);
  const rev = await seedInvite(t.org.id, t.userIds.admin, "rev@seats.test", "member", "v".repeat(32));
  await inv.revokeInvitation(t.actors.admin, rev.id);
  expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(0);
  expect(await invitationRepo.listPendingInvitations(t.org.id)).toHaveLength(0);

  const fresh = await inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "new@seats.test", role: "member" });
  const days = (Date.parse(fresh.expiresAt) - Date.now()) / 86_400_000;
  expect(days).toBeGreaterThan(13.99); expect(days).toBeLessThanOrEqual(14);

  await expect(inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "NEW@seats.test", role: "member" })).rejects.toThrow(/pending/);
  await expect(inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "Member@Seats.test", role: "member" })).rejects.toThrow(/already a member/);
  await expect(inv.inviteMembers(t.actors.admin, { orgId: t.org.id, invites: [{ email: "a@seats.test", role: "member" }, { email: "A@seats.test", role: "viewer" }] })).rejects.toThrow(/more than once/);
  await expect(inv.inviteMembers(t.actors.admin, { orgId: t.org.id, invites: [{ email: "ok@seats.test", role: "member" }, { email: "new@seats.test", role: "viewer" }] })).rejects.toThrow();
  expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(1);
  // previously expired / revoked addresses can be invited again
  await inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "old@seats.test", role: "member" });
  await inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "rev@seats.test", role: "member" });
  expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(3);

  // resend an expired invitation keeps the role, and one that is pending keeps its seat
  const again = await inv.resendInvitation(t.actors.admin, exp.id).catch((e) => e);
  expect(again).toBeInstanceOf(Error); // old@ already has a newer pending invitation
  const exp2 = await seedInvite(t.org.id, t.userIds.admin, "late@seats.test", "admin", "l".repeat(32), -1);
  const resent = await inv.resendInvitation(t.actors.admin, exp2.id);
  expect(resent).toMatchObject({ email: "late@seats.test", role: "admin", revokedAt: null });
  expect((await invitationRepo.findInvitationById(t.org.id, exp2.id))?.revokedAt).not.toBeNull();
  const resent2 = await inv.resendInvitation(t.actors.admin, resent.id);
  expect(resent2.role).toBe("admin");
  expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(4);

  // wrong account is refused, right one becomes a full member
  const raw = "n".repeat(32);
  getDb().run(`update invitations set token_hash = '${hashToken(raw)}' where id = '${fresh.id}'` as any);
  const stranger = await userRepo.insertUser({ email: "stranger@seats.test", name: "S", passwordHash: "x" });
  const invitee = await userRepo.insertUser({ email: "New@Seats.test", name: "N", passwordHash: "x" });
  await expect(inv.acceptInvitation(stranger.id, { token: raw })).rejects.toThrow(/different email/);
  expect(await memberRepo.findMember(t.org.id, stranger.id)).toBeNull();
  expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(4);
  const member = await inv.acceptInvitation(invitee.id, { token: raw });
  expect(member).toMatchObject({ status: "active", role: "member" });
  expect(await memberService.resolveActor(invitee.id, t.org.id)).not.toBeNull();
  expect(await memberRepo.countActiveMembers(t.org.id)).toBe(5);
  expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(5);
  expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(3);
});

it("free plan: 2 members + stale invitations can still invite one, not two", async () => {
  const t = await createTenant("free", "free");
  for (const role of ["member", "viewer"] as const) {
    const m = (await memberRepo.findMember(t.org.id, t.userIds[role]))!;
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m.id });
  }
  await seedInvite(t.org.id, t.userIds.admin, "stale@free.test", "member", "s".repeat(32), -20);
  const r = await seedInvite(t.org.id, t.userIds.admin, "gone@free.test", "member", "g".repeat(32));
  await inv.revokeInvitation(t.actors.admin, r.id);
  await expect(inv.inviteMembers(t.actors.admin, { orgId: t.org.id, invites: [{ email: "x@free.test", role: "member" }, { email: "y@free.test", role: "member" }] })).rejects.toThrow(/seats/);
  expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(0);
  const one = await inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "x@free.test", role: "viewer" });
  await expect(inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "y@free.test", role: "member" })).rejects.toThrow(/seats/);
  // a full org can still re-send its own pending invitation
  expect((await inv.resendInvitation(t.actors.admin, one.id)).role).toBe("viewer");
  // a former member can be invited again once a seat is free
  await inv.revokeInvitation(t.actors.admin, (await invitationRepo.listPendingInvitations(t.org.id))[0]!.id);
  await inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "viewer@free.test", role: "member" });
});

it("deleted workspace: invitation refused and sessions stop defaulting to it", async () => {
  const t = await createTenant("gone", "growth");
  const raw = "d".repeat(32);
  await seedInvite(t.org.id, t.userIds.admin, "late@gone.test", "member", raw);
  const user = await userRepo.insertUser({ email: "late@gone.test", name: "L", passwordHash: "x" });
  const { token } = await sessionService.createSessionToken(t.userIds.member);
  getDb().update(sessions).set({ activeOrgId: t.org.id }).where(eq(sessions.tokenHash, hashToken(token))).run();
  expect((await sessionService.resolveSession(token))?.activeOrgId).toBe(t.org.id);
  await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: t.org.slug });
  await expect(inv.acceptInvitation(user.id, { token: raw })).rejects.toThrow(/deleted/);
  expect(await memberRepo.findMembershipRecord(t.org.id, user.id)).toBeNull();
  expect(getDb().select().from(sessions).where(eq(sessions.tokenHash, hashToken(token))).get()?.activeOrgId).toBeNull();
  expect((await orgRepo.findOrgById(t.org.id))?.archivedAt).not.toBeNull();
});
